-- ADR-0187 Migration A (aditiva): tabela oficial de NCM (Siscomex) + carga inicial + ncm_consultar +
-- `ncm_vigente` no resumo do Estoque. Sem FK aqui: a FK `NOT VALID` vem na Migration B.
-- GLOBAL, sem org_id, de propósito: é a nomenclatura pública, igual para toda org. Escrita só
-- service_role (atualização via Management API); leitura autenticada (molde sonar_snapshots).
create table if not exists public.ncm_oficial (
  codigo text primary key check (codigo ~ '^[0-9]{8}$'),
  descricao text not null,             -- composta: capítulo › posição › ... › item (gerar-sql.ts)
  data_inicio date not null,
  data_fim date not null,              -- 9999-12-31 = sem fim
  atualizado_em timestamptz not null default now()
);

alter table public.ncm_oficial enable row level security;
-- `create policy` não tem `if not exists`; o drop antes torna o re-run seguro (db push não é transacional).
drop policy if exists "ncm_oficial: select autenticado" on public.ncm_oficial;
create policy "ncm_oficial: select autenticado"
  on public.ncm_oficial for select to authenticated using (true);
grant select on public.ncm_oficial to authenticated;
-- escrita: nenhuma policy de insert/update/delete — só service_role

-- Carga inicial: 10.516 códigos, gerada por
-- `deno run --allow-read scripts/ncm/gerar-sql.ts --modo seed --entrada <ncm.json do Siscomex>`.

-- Vigência calculada na consulta (não gravada): resolução com data futura passa a valer no dia certo.
-- Só devolve códigos existentes; ausente = não existe na tabela oficial.
create or replace function public.ncm_consultar(p_codigos text[])
returns table(codigo text, descricao text, vigente boolean)
language sql stable security definer
set search_path = ''
as $$
  select o.codigo, o.descricao, current_date between o.data_inicio and o.data_fim
  from public.ncm_oficial o
  where o.codigo = any(p_codigos)
$$;
revoke all on function public.ncm_consultar(text[]) from public;
grant execute on function public.ncm_consultar(text[]) to authenticated, service_role;

-- Resumo do Estoque ganha `ncm_vigente`: null sem NCM; false se o NCM não existe na tabela oficial;
-- senão a vigência de hoje. Retorno continua `json`, então `create or replace` basta.
-- Corpo idêntico a 20260924141352_estoque_rpc_tamanho.sql + `ncm_vigente`.
create or replace function public.produtos_estoque_resumo()
returns json
language sql stable security definer
set search_path = ''
as $$
  with org as (
    select public.current_org_id() as id
  ),
  canonical as (
    select distinct on (f.codigo_pai)
      f.id,
      f.codigo_pai,
      f.nome_pai,
      f.descricao_pai,
      f.capa_storage_path,
      f.capa_ml_picture_id,
      f.variacao_principal_codigo,
      f.fornecedor,
      f.unidade,
      f.origem,
      f.ml_item_id,
      f.criado_em,
      f.ncm,
      f.cest,
      f.origem_nfe,
      f.fci,
      f.tributacao_icms,
      f.tributacao_icms_regime,
      f.can_invoice
    from public.familias f
    cross join org
    where f.org_id = org.id
      and f.kit_multiplicador is null
    order by f.codigo_pai, f.criado_em desc
  ),
  vars as (
    select
      v.familia_id,
      v.codigo,
      v.nome,
      v.cor,
      v.gtin,
      v.estoque,
      v.custo,
      v.imagem_path,
      v.ml_picture_id
    from public.variacoes v
    cross join org
    join canonical c on c.id = v.familia_id
    where v.org_id = org.id
  ),
  capa as (
    select
      c.id as familia_id,
      coalesce(
        c.capa_storage_path,
        (select vp.imagem_path from vars vp
          where vp.familia_id = c.id and vp.codigo = c.variacao_principal_codigo
            and vp.imagem_path is not null limit 1),
        (select vp.imagem_path from vars vp
          where vp.familia_id = c.id and vp.imagem_path is not null
          order by vp.codigo limit 1)
      ) as capa_storage_path,
      coalesce(
        c.capa_ml_picture_id,
        (select vp.ml_picture_id from vars vp
          where vp.familia_id = c.id and vp.codigo = c.variacao_principal_codigo
            and vp.ml_picture_id is not null limit 1),
        (select vp.ml_picture_id from vars vp
          where vp.familia_id = c.id and vp.ml_picture_id is not null
          order by vp.codigo limit 1)
      ) as capa_ml_picture_id
    from canonical c
  ),
  produtos as (
    select
      c.id as familia_id,
      c.codigo_pai,
      c.nome_pai,
      c.descricao_pai,
      coalesce(sum(v.estoque), 0)::bigint as saldo_total,
      count(v.codigo)::int as qtd_skus,
      cap.capa_storage_path,
      cap.capa_ml_picture_id,
      c.fornecedor,
      c.unidade,
      c.origem::text as origem,
      c.ml_item_id,
      c.criado_em,
      c.ncm,
      c.cest,
      c.origem_nfe,
      c.fci,
      c.tributacao_icms,
      c.tributacao_icms_regime,
      c.can_invoice,
      coalesce(array_agg(v.gtin order by v.codigo) filter (where v.gtin is not null), '{}') as gtins,
      coalesce(array_agg(v.codigo order by v.codigo), '{}') as codigos,
      coalesce(array_agg(v.cor order by v.codigo) filter (where v.cor is not null), '{}') as cores,
      coalesce(array_agg(v.nome order by v.codigo) filter (where v.nome is not null), '{}') as nomes,
      case when count(v.codigo) = 1 then max(v.codigo) else null end as sku_unico
    from canonical c
    join capa cap on cap.familia_id = c.id
    left join vars v on v.familia_id = c.id
    group by
      c.id, c.codigo_pai, c.nome_pai, c.descricao_pai,
      cap.capa_storage_path, cap.capa_ml_picture_id,
      c.fornecedor, c.unidade, c.origem, c.ml_item_id, c.criado_em,
      c.ncm, c.cest, c.origem_nfe, c.fci, c.tributacao_icms, c.tributacao_icms_regime, c.can_invoice
  ),
  kpis as (
    select
      (select count(*) from produtos)::int as produtos,
      count(v.codigo)::int as skus,
      coalesce(sum(v.estoque) filter (where v.estoque > 0), 0)::bigint as unidades,
      count(v.codigo) filter (where v.estoque <= 0)::int as skus_sem_estoque,
      coalesce(sum(v.custo * v.estoque) filter (where v.estoque > 0 and v.custo is not null), 0)::numeric as valor_em_estoque,
      count(v.codigo) filter (where v.estoque > 0 and v.custo is null)::int as skus_sem_custo
    from vars v
  )
  select json_build_object(
    'kpis', (select row_to_json(k) from kpis k),
    'produtos', coalesce(
      (select json_agg(
        json_build_object(
          'familia_id', p.familia_id,
          'codigo_pai', p.codigo_pai,
          'nome_pai', p.nome_pai,
          'descricao_pai', p.descricao_pai,
          'saldo_total', p.saldo_total,
          'qtd_skus', p.qtd_skus,
          'tem_tamanho', exists (
            select 1 from public.variacoes vp
            where vp.familia_id = (
                select fp.id from public.familias fp
                where fp.org_id = org.id and fp.codigo_pai = p.codigo_pai
                  and fp.kit_multiplicador is null and fp.ml_item_id is not null
                order by fp.publicado_em desc nulls last limit 1)
              and nullif(btrim(vp.tamanho), '') is not null and not vp.excluida_da_publicacao
          ),
          'capa_storage_path', p.capa_storage_path,
          'capa_ml_picture_id', p.capa_ml_picture_id,
          'fornecedor', p.fornecedor,
          'unidade', p.unidade,
          'origem', p.origem,
          'ml_item_id', p.ml_item_id,
          'criado_em', p.criado_em,
          'gtins', p.gtins,
          'codigos', p.codigos,
          'cores', p.cores,
          'nomes', p.nomes,
          'sku_unico', p.sku_unico,
          'ncm', p.ncm,
          'cest', p.cest,
          'origem_nfe', p.origem_nfe,
          'fci', p.fci,
          'tributacao_icms', p.tributacao_icms,
          'tributacao_icms_regime', p.tributacao_icms_regime,
          'can_invoice', p.can_invoice,
          'ncm_vigente', case
            when p.ncm is null then null
            else coalesce((select current_date between o.data_inicio and o.data_fim
                           from public.ncm_oficial o where o.codigo = p.ncm), false)
          end
        )
        order by p.nome_pai
      ) from produtos p),
      '[]'::json
    )
  )
  from org
  where org.id is not null
$$;
revoke all on function public.produtos_estoque_resumo() from public;
grant execute on function public.produtos_estoque_resumo() to authenticated;
